        if (command === 'git diff --cached --stat') return '';
        if (command.indexOf('git rev-list --count') === 0) return '2';
        if (command.indexOf('git fetch') === 0) return '';
        if (command.indexOf('git rev-parse origin/') === 0) return 'basesha123';
